@Component("riskAssessment-handler")
@ProcessingGroup("riskAssessment-processing-group")
public class RiskAssessmentEventHandler {
	
	// core constructor
	RiskAssessmentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRiskAssessmentEvent
     */
    @EventHandler
    public void handle( CreateRiskAssessmentEvent event) {
        entityManager.persist(new RiskAssessment(event.getRiskAssessmentId(), event.getScore(), event.getAssessedAt(), event.getModelVersion(), event.getNotes(), event.getApplication(), event.getDecision()));
    }

    /*
     * @param	event UpdateRiskAssessmentEvent
     */
    @EventHandler
    public RiskAssessment handle( UpdateRiskAssessmentEvent event) {
    	entityManager.merge(new RiskAssessment(event.getRiskAssessmentId(), event.getScore(), event.getAssessedAt(), event.getModelVersion(), event.getNotes(), event.getApplication(), event.getDecision()));
    }
    
    /*
     * @param	event DeleteRiskAssessmentEvent
     */
    @EventHandler
    public void on( DeleteRiskAssessmentEvent event) {
    	RiskAssessment entity = new RiskAssessment();
   
    	// ------------------------------------------
    	// apply the RiskAssessmentId
    	// ------------------------------------------
    	entity.setRiskAssessmentId( event.getRiskAssessmentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RiskAssessmentRepository riskAssessmentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RiskAssessmentEventHandler.class.getName());

}
